#include <zephyr/ztest.h>
#include <zephyr/device.h>
#include <zephyr/drivers/nvmem.h>

#if DT_HAS_COMPAT_STATUS_OKAY(test_nvmem)
#define NVMEM_DEVICE_NODE DT_COMPAT_GET_ANY_STATUS_OKAY(test_nvmem)
#else
#error "No test_nvmem compatible node found"
#define NVMEM_DEVICE_NODE DT_INVALID_NODE
#endif

static const struct device *const nvmem_dev = DEVICE_DT_GET(NVMEM_DEVICE_NODE);

static void *nvmem_setup(void)
{
	zassert_true(device_is_ready(nvmem_dev), "NVMEM device is not ready");

	return NULL;
}

ZTEST(nvmem_api, test_nvmem_api)
{
	uint8_t wbuf[] = {0x01, 0x02, 0x03, 0x04};
	uint8_t rbuf[sizeof(wbuf)];
	int ret;
	const struct nvmem_cell_config cell = {
		.offset = 0,
		.size = sizeof(wbuf),
	};

	ret = nvmem_cell_write(nvmem_dev, &cell, wbuf, sizeof(wbuf), 0);
	zassert_equal(ret, 0, "Failed to write to NVMEM cell");

	ret = nvmem_cell_read(nvmem_dev, &cell, rbuf, sizeof(rbuf), 0);
	zassert_equal(ret, 0, "Failed to read from NVMEM cell");

	zassert_mem_equal(wbuf, rbuf, sizeof(wbuf), "Read data does not match written data");
}

ZTEST(nvmem_api, test_nvmem_cell_bounds_offbyone)
{
	uint8_t buf[4];
	int ret;
	const struct nvmem_cell_config cell = {
		.offset = 0,
		.size = 4,
	};

	/* Read at the boundary, this should fail */
	ret = nvmem_cell_read(nvmem_dev, &cell, buf, 1, 4);
	zassert_equal(ret, -EINVAL, "Did not get EINVAL for off-by-one read");

	/* Write at the boundary, this should fail */
	ret = nvmem_cell_write(nvmem_dev, &cell, buf, 1, 4);
	zassert_equal(ret, -EINVAL, "Did not get EINVAL for off-by-one write");
}

ZTEST(nvmem_api, test_nvmem_cell_bounds_overflow)
{
	uint8_t buf[4];
	int ret;
	const struct nvmem_cell_config cell = {
		.offset = 0,
		.size = 4,
	};

	/* Read with overflow, this should fail */
	ret = nvmem_cell_read(nvmem_dev, &cell, buf, 5, 0);
	zassert_equal(ret, -EINVAL, "Did not get EINVAL for overflow read");

	/* Write with overflow, this should fail */
	ret = nvmem_cell_write(nvmem_dev, &cell, buf, 5, 0);
	zassert_equal(ret, -EINVAL, "Did not get EINVAL for overflow write");
}

ZTEST_SUITE(nvmem_api, NULL, nvmem_setup, NULL, NULL, NULL);
